 // Gate 5 — Limit Gate (杜門): shell access + process visibility.
 "HACHIMON_GATE_5" => {
 info!("杜門 — Gate 5: Limit Gate activated");
 let cfg: Value = serde_json::from_str(payload)
.ok()
.and_then(|v: Value| v.get("config").cloned())
.unwrap_or_else(|| json!({}));

