#[cfg(test)]
mod tests {
 use super::*;

 // ---- Keccak-256 ------------------------------------------------

 #[test]
 fn keccak256_empty() {
 let hash = keccak256(b"");
 let expected = hex_decode(
 "c5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470",
 )
.unwrap();
