 }

 // ---- Hex helpers ------------------------------------------------

 #[test]
 fn hex_encode_decode_roundtrip() {
 let original = vec![0xde, 0xad, 0xbe, 0xef, 0x00, 0xff];
 let encoded = hex_encode(&original);
 let decoded = hex_decode(&encoded).unwrap();
 assert_eq!(original, decoded);
 }

 #[test]
 fn hex_decode_0x_prefix() {
