 assert_eq!(decoded, vec![0xde, 0xad, 0xbe, 0xef]);
 }

 #[test]
 fn hex_decode_odd_length_error() {
 let result = hex_decode("abc");
 assert!(result.is_err());
 assert!(result.unwrap_err().contains("odd"));
 }

 #[test]
 fn hex_decode_invalid_chars_error() {
