 // ── Multi-transform pipeline ──────────────────────────────────────

 #[test]
 fn multi_transform_pipeline_roundtrip() {
 let transforms = vec![
 "base64".to_string(),
 "prepend:START_".to_string(),
 "append:_END".to_string(),
 ];
 let data = b"multi step payload";
