 fn AmsiOpenSession(amsi_context: HAMSICONTEXT, amsi_session: *mut HAMSISESSION) -> HRESULT;
 fn AmsiCloseSession(amsi_context: HAMSICONTEXT, amsi_session: HAMSISESSION);
 fn AmsiScanBuffer(
 amsi_context: HAMSICONTEXT,
 buffer: LPCVOID,
 length: ULONG,
 content_name: LPCWSTR,
