 }
 let items = exception_directory.1 / 12;
 let rva = (address - module) as u32;

 for _ in 0..items {
 if rva >= (*rt).begin_addr && rva < (*rt).end_addr {
 return get_rbp_push_offset(module, *rt);
 }
 rt = rt.add(1);
 }
