use core::arch::asm;
use core::ptr::null_mut;

use super::def::{
 ImageDosHeader, ImageNtHeaders, LoaderDataTableEntry, PebLoaderData, IMAGE_DOS_SIGNATURE,
 IMAGE_NT_SIGNATURE, PEB,
