}

#[cfg(target_arch = "x86_64")]
#[inline(always)]
pub unsafe fn recycled4(ssn: u32, gadget: usize, a1: usize, a2: usize, a3: usize, a4: usize) -> i32 {
 let ret: i32;
 asm!(
 "mov r10, rcx",
 "jmp r11",
 in("rcx") a1,
 in("rdx") a2,
 in("r8") a3,
 in("r9") a4,
 in("eax") ssn,
