const fn djb2_const(bytes: &[u8]) -> u32 {
 let mut hash: u32 = 5381;
 let mut i = 0;
 while i < bytes.len() {
 hash = ((hash << 5).wrapping_add(hash)).wrapping_add(bytes[i] as u32);
 i += 1;
 }
 hash
}

