 // remaining fields omitted -- we only need loader_data
}

#[repr(C)]
struct ImageDosHeader {
 e_magic: u16,
 e_cblp: u16,
 e_cp: u16,
 e_crlc: u16,
 e_cparhdr: u16,
 e_minalloc: u16,
 e_maxalloc: u16,
 e_ss: u16,
 e_sp: u16,
 e_csum: u16,
 e_ip: u16,
 e_cs: u16,
 e_lfarlc: u16,
 e_ovno: u16,
 e_res: [u16; 4],
 e_oemid: u16,
 e_oeminfo: u16,
 e_res2: [u16; 10],
 e_lfanew: i32,
}

#[repr(C)]
struct ImageFileHeader {
 machine: u16,
 number_of_sections: u16,
 time_date_stamp: u32,
