 // Initialize hooks
 initialize_hooks();

 // Set up UNICODE_STRING for the image path
 let mut image_path: alloc::vec::Vec<u16> = "\\??\\C:\\Windows\\System32\\calc.exe"
.encode_utf16()
.chain(once(0))
