 };

 unsafe { RtlInitUnicodeString(&mut nt_image_path, image_path.as_ptr()) };

 // Create the process parameters
 let mut process_parameters: *mut RTL_USER_PROCESS_PARAMETERS = null_mut();
 let status = unsafe {
