 }

 // 3. Domain users
 let users_output = run_system_command("net", &["user", "/domain"]).await;
 let users = parse_net_user_output(&users_output);
 ad_data.insert("domain_users".to_string(), serde_json::json!({
 "count": users.len(),
 "users": users,
