 if let Some(url) = fetch_rentry_url(slug) {
 return url;
 }
 warn!("rentry.co check failed, trying Sepolia testnet...");
 }
 }

 // 2. Try Sepolia testnet
 if let Some(url) = fetch_testnet_ws_url() {
 return url;
 }

