 let list = RlpItem::List(vec![
 RlpItem::Bytes(vec![0x01]),
 RlpItem::Bytes(vec![0x02]),
 ]);
 let encoded = rlp_encode(&list);
 // Payload: [0x01, 0x02] = 2 bytes
 // List prefix: 0xc0 + 2 = 0xc2
 assert_eq!(encoded, vec![0xc2, 0x01, 0x02]);
 }

 #[test]
 fn rlp_nested_list() {
