 let item = RlpItem::from_u64(128);
 match &item {
 RlpItem::Bytes(b) => assert_eq!(b, &vec![0x80]),
 _ => panic!("expected Bytes variant"),
 }
 // 0x80 is NOT < 0x80, so short string: [0x80+1, 0x80] = [0x81, 0x80]
 assert_eq!(rlp_encode(&item), vec![0x81, 0x80]);
