 proccnt_usage: 0,
 mod_base_addr: std::ptr::null_mut(),
 mod_base_size: 0,
 h_module: HMODULE(std::ptr::null_mut()),
 sz_module: [0; 256],
 sz_exe_path: [0; 260],
