 let status = crate::recycled::nt_protect_virtual_memory(
 CURRENT_PROCESS,
 &mut stub_base,
 &mut stub_size,
 PAGE_EXECUTE_READ_RAW,
 &mut old_prot,
 );
 if status < 0 {
