// ── Own image base ────────────────────────────────────────────────────────────

unsafe fn get_own_image_base() -> *mut u8 {
 #[cfg(target_arch = "x86_64")]
 {
 let peb: usize;
 core::arch::asm!("mov {}, gs:[0x60]", out(reg) peb, options(nostack, readonly, pure));
 if peb == 0 { return null_mut(); }
 *(peb as *const *mut u8).add(2)
 }
 #[cfg(not(target_arch = "x86_64"))]
 { null_mut() }
}

