 crate::recycled::nt_free_virtual_memory(h_proc_raw, &mut base, &mut sz, 0x8000);
 crate::recycled::nt_terminate_process(h_proc_raw, 1);
 crate::recycled::nt_close(h_thread_raw);
 crate::recycled::nt_close(h_proc_raw);
