 CURRENT_PROCESS,
 &mut base_rw,
 &mut size_rw,
 PAGE_READWRITE_RAW,
 &mut old_protect,
 );
 if status < 0 {
 return Err(ntstatus_i32_to_error(status));
 }

 std::ptr::copy_nonoverlapping(
 address.cast::<u8>(),
 module.cast::<u8>(),
 image_size,
 );
