 pub const EDO_SLEEP_MS: &[u64] = &[];

 // ── Edo Dead Drop: Autonomous C2 Channels ─────────────────────────

 /// Master toggle for dead drop polling.
 pub const EDO_DROP_ENABLED: bool = false;

 /// Rentry.co slug for Google Translate proxy channel.
