 (-1isize) as usize,
 &mut h_dup as *mut usize as usize,
 WORKER_FACTORY_ALL as usize,
 0usize,
 0usize,
 ],
 );
 if dup_st != 0 || h_dup == 0 { continue; }

 // Check type name
