 }
 break;
 }

 Err(anyhow!("PoolParty: no TpWorkerFactory handle found in PID {}", target_pid))
}

unsafe fn is_type_worker_factory(handle: usize) -> bool {
 let mut buf = vec![0u8; 256];
 let mut ret_len: u32 = 0;
